/*
  أيقونات Material UI (@mui/icons-material) المدمجة مع تحديد صريح للأبعاد (width / height / minWidth / maxWidth)
  عبر خصائص الـ SVG والـ Inline Styles حتى لا يتغير حجم الأيقونة أو يكبر أبداً في Next.js أو الموبايل.
*/
function resolveIconPixelSize(size, className = '') {
  if (typeof size === 'number') return size;
  if (className.includes('w-9') || className.includes('h-9')) return 32;
  if (className.includes('w-6') || className.includes('h-6')) return 22;
  if (className.includes('w-4') || className.includes('h-4')) return 16;
  return 20;
}

function MuiSvgIcon({ children, size, className = 'w-5 h-5', style = {} }) {
  const px = resolveIconPixelSize(size, className);
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={px}
      height={px}
      fill="currentColor"
      className={`mui-svg-icon ${className}`}
      style={{
        width: `${px}px`,
        height: `${px}px`,
        minWidth: `${px}px`,
        minHeight: `${px}px`,
        maxWidth: `${px}px`,
        maxHeight: `${px}px`,
        flexShrink: 0,
        display: 'inline-block',
        verticalAlign: 'middle',
        ...style
      }}
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

